package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarUtils.parseOctal
 */
public class TarUtils_parseOctal_TriageGen0Test {





    @Test
    public void testParseOctal_WithTrailingSpacesAndNulls() {
        // Testing the logic: while (start < end && (trailer == 0 || trailer == ' '))
        byte[] buffer = "000123  \0\0".getBytes();
        // Note: \0 in Java string literal is a null byte. 
        // To be safe with byte arrays:
        byte[] explicitBuffer = new byte[10];
        System.arraycopy("000123".getBytes(), 0, explicitBuffer, 0, 6);
        explicitBuffer[6] = ' ';
        explicitBuffer[7] = ' ';
        explicitBuffer[8] = 0;
        explicitBuffer[9] = 0;

        long result = TarUtils.parseOctal(explicitBuffer, 0, 10);
        assertEquals(83L, result);
    }
















}

