public class TarUtils_parseOctal_TriageGen0Test {



















    @Test
    public void testParseOctal_AllSpaces() {
        // If the buffer is all spaces, the while loop for trailing/leading might 
        // reduce end to start, resulting in 0.
        byte[] buffer = "      ".getBytes();
        // length must be at least 2
        long result = TarUtils.parseOctal(buffer, 0, 6);
        assertEquals(0L, result);
    }


